var e=[{question:`¿Qué es EducaLabCR?`,answer:`EducaLabCR integra tecnología, formación e innovación aplicada en Costa Rica. El ecosistema reúne Sigma Docente, TEKU, LUMA, Relay, la práctica de idoneidad docente y taskOs.`},{question:`¿Qué es Sigma Docente?`,answer:`Sigma Docente es el sistema de gestión docente para instituciones, con registro académico, planeamiento con inteligencia artificial, Ágora y reportes. La demostración publica cuatro planes en colones.`},{question:`¿Qué es TEKU?`,answer:`TEKU es un piloto para construir una investigación paso a paso, con conversación, decisiones y fuentes. El piloto está en línea.`},{question:`¿Qué es LUMA?`,answer:`LUMA crea presentaciones y las convierte en clases guiadas con voz, subtítulos y cursor sincronizado. La demostración está en línea. Este sitio no publica planes ni cupos de uso.`},{question:`¿Qué es Relay?`,answer:`Relay es el constructor de agentes de inteligencia artificial. La entrada pública está en línea: se diseñan agentes, se conectan canales y la atención queda en un solo panel.`},{question:`¿Qué es la práctica de idoneidad docente?`,answer:`Es el simulador de las pruebas de idoneidad docente del MEP, con casos pedagógicos y tutoría de inteligencia artificial. El simulador está en línea.`},{question:`¿Qué es taskOs?`,answer:`taskOs es el gestor de tareas para una institución o para varias organizaciones. La aplicación está en línea.`},{question:`¿Hay formación para docentes?`,answer:`Sí. EducaLabCR prepara cursos y capacitaciones a la medida para docentes e instituciones. No hay un catálogo cerrado: se conversa el programa.`},{question:`¿Cómo me comunico con EducaLabCR?`,answer:`Por WhatsApp, al +506 7014 7031, o al correo info@educalabcr.com.`}];
